<title>Nebula Mission Control — Asteria-7</title>
<style>
/* ===== DESIGN TOKENS ===== */
:root {
  --color-bg-primary: #0a0e1a;
  --color-bg-secondary: #111827;
  --color-bg-tertiary: #1a2235;
  --color-bg-elevated: #1e293b;
  --color-bg-overlay: rgba(10,14,26,0.85);
  --color-text-primary: #e8ecf4;
  --color-text-secondary: #94a3b8;
  --color-text-muted: #64748b;
  --color-accent: #06b6d4;
  --color-accent-hover: #22d3ee;
  --color-accent-dim: rgba(6,182,212,0.15);
  --color-warning: #f59e0b;
  --color-warning-dim: rgba(245,158,11,0.15);
  --color-danger: #ef4444;
  --color-danger-dim: rgba(239,68,68,0.15);
  --color-success: #10b981;
  --color-success-dim: rgba(16,185,129,0.15);
  --color-border: #1e293b;
  --color-border-light: #334155;
  --color-grid: rgba(148,163,184,0.04);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 20px rgba(6,182,212,0.1);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Cascadia Code", "Fira Code", "JetBrains Mono", Consolas, monospace;
  --font-size-xs: 11px;
  --font-size-sm: 12px;
  --font-size-base: 13px;
  --font-size-md: 14px;
  --font-size-lg: 16px;
  --font-size-xl: 20px;
  --font-size-2xl: 24px;
  --font-size-3xl: 32px;
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 12px;
  --spacing-base: 16px;
  --spacing-lg: 20px;
  --spacing-xl: 24px;
  --spacing-2xl: 32px;
  --spacing-3xl: 48px;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
  --sidebar-width: 240px;
  --sidebar-collapsed: 56px;
  --header-height: 56px;
}

[data-theme="light"] {
  --color-bg-primary: #f1f5f9;
  --color-bg-secondary: #ffffff;
  --color-bg-tertiary: #e2e8f0;
  --color-bg-elevated: #ffffff;
  --color-bg-overlay: rgba(241,245,249,0.85);
  --color-text-primary: #0f172a;
  --color-text-secondary: #475569;
  --color-text-muted: #94a3b8;
  --color-accent: #0891b2;
  --color-accent-hover: #06b6d4;
  --color-accent-dim: rgba(8,145,178,0.1);
  --color-border: #cbd5e1;
  --color-border-light: #e2e8f0;
  --color-grid: rgba(148,163,184,0.08);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-glow: 0 0 20px rgba(8,145,178,0.08);
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 14px; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  font-size: var(--font-size-base);
  color: var(--color-text-primary);
  background: var(--color-bg-primary);
  line-height: 1.5;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input { font: inherit; color: inherit; background: none; border: none; outline: none; }
a { color: var(--color-accent); text-decoration: none; }
ul, ol { list-style: none; }
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: var(--radius-sm); }

/* ===== GRID TEXTURE ===== */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(var(--color-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-grid) 1px, transparent 1px);
  background-size: 40px 40px;
  pointer-events: none;
  z-index: 0;
}

/* ===== LAYOUT ===== */
.app-layout {
  display: grid;
  grid-template-columns: var(--sidebar-width) 1fr;
  grid-template-rows: var(--header-height) 1fr;
  grid-template-areas:
    "header header"
    "sidebar main";
  height: 100vh;
  width: 100vw;
  position: relative;
  z-index: 1;
}

/* ===== HEADER ===== */
.header {
  grid-area: header;
  display: flex;
  align-items: center;
  padding: 0 var(--spacing-base);
  background: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  gap: var(--spacing-base);
  z-index: 100;
}
.header-logo {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-weight: 700;
  font-size: var(--font-size-md);
  letter-spacing: 0.5px;
  white-space: nowrap;
}
.header-logo svg { flex-shrink: 0; }
.header-mission {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
}
.header-mission .mission-name {
  color: var(--color-accent);
  font-weight: 600;
  font-family: var(--font-mono);
}
.header-mission .mission-duration {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  background: var(--color-bg-tertiary);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}
.header-spacer { flex: 1; }
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}
.header-btn {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: 6px 10px;
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  position: relative;
  white-space: nowrap;
}
.header-btn:hover, .header-btn:focus-visible {
  background: var(--color-bg-tertiary);
  color: var(--color-text-primary);
}
.header-btn .badge {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-danger);
}
.header-btn .badge-count {
  position: absolute;
  top: -2px;
  right: -2px;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  background: var(--color-danger);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}
.header-search {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: 6px 12px;
  border-radius: var(--radius-md);
  background: var(--color-bg-tertiary);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-width: 180px;
  justify-content: space-between;
}
.header-search:hover { border-color: var(--color-accent); }
.header-search kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
}
.header-utc {
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  min-width: 70px;
  text-align: right;
}
.header-link-status {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}
.header-link-status .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-success);
}
.header-link-status .dot.warn { background: var(--color-warning); }
.header-link-status .dot.error { background: var(--color-danger); }

/* ===== SIDEBAR ===== */
.sidebar {
  grid-area: sidebar;
  background: var(--color-bg-secondary);
  border-right: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  transition: width var(--transition-base);
  z-index: 90;
}
.sidebar.collapsed { width: var(--sidebar-collapsed); }
.sidebar-nav { flex: 1; padding: var(--spacing-sm) 0; }
.sidebar-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  padding: 10px var(--spacing-base);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
  white-space: nowrap;
  border-left: 3px solid transparent;
}
.sidebar-item:hover { background: var(--color-bg-tertiary); color: var(--color-text-primary); }
.sidebar-item:focus-visible { background: var(--color-accent-dim); color: var(--color-accent); }
.sidebar-item.active {
  color: var(--color-accent);
  background: var(--color-accent-dim);
  border-left-color: var(--color-accent);
  font-weight: 600;
}
.sidebar-item svg { flex-shrink: 0; width: 20px; height: 20px; }
.sidebar-item .item-label { overflow: hidden; text-overflow: ellipsis; }
.sidebar-item .item-badge {
  margin-left: auto;
  background: var(--color-bg-tertiary);
  color: var(--color-text-muted);
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 10px;
  min-width: 20px;
  text-align: center;
}
.sidebar-item.active .item-badge { background: var(--color-accent); color: #fff; }
.sidebar-item .item-badge.warn { background: var(--color-warning); color: #000; }
.sidebar-item .item-badge.danger { background: var(--color-danger); color: #fff; }
.sidebar.collapsed .item-label,
.sidebar.collapsed .item-badge { display: none; }
.sidebar.collapsed .sidebar-item { justify-content: center; padding: 10px; }
.sidebar-footer {
  padding: var(--spacing-sm) var(--spacing-base);
  border-top: 1px solid var(--color-border);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-align: center;
}
.sidebar-toggle {
  display: none;
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 200;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  align-items: center;
  justify-content: center;
  color: var(--color-text-secondary);
  box-shadow: var(--shadow-md);
}

/* ===== MAIN CONTENT ===== */
.main-content {
  grid-area: main;
  overflow-y: auto;
  overflow-x: hidden;
  padding: var(--spacing-xl);
  position: relative;
}
.main-content::-webkit-scrollbar { width: 6px; }
.main-content::-webkit-scrollbar-track { background: transparent; }
.main-content::-webkit-scrollbar-thumb { background: var(--color-border-light); border-radius: 3px; }

/* ===== SECTION HEADER ===== */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-lg);
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}
.section-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  letter-spacing: -0.3px;
}
.section-subtitle {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  margin-top: 2px;
}
.time-range-group {
  display: flex;
  gap: 2px;
  background: var(--color-bg-tertiary);
  border-radius: var(--radius-md);
  padding: 2px;
}
.time-range-btn {
  padding: 5px 14px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
}
.time-range-btn:hover { color: var(--color-text-primary); }
.time-range-btn.active {
  background: var(--color-accent);
  color: #fff;
}

/* ===== KPI CARDS ===== */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-base);
  margin-bottom: var(--spacing-xl);
}
.kpi-card {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-fast);
}
.kpi-card:hover { border-color: var(--color-border-light); box-shadow: var(--shadow-md); }
.kpi-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
}
.kpi-card.nominal::before { background: var(--color-success); }
.kpi-card.warning::before { background: var(--color-warning); }
.kpi-card.danger::before { background: var(--color-danger); }
.kpi-card.info::before { background: var(--color-accent); }
.kpi-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--spacing-sm);
}
.kpi-value {
  font-family: var(--font-mono);
  font-size: var(--font-size-2xl);
  font-weight: 700;
  line-height: 1.2;
}
.kpi-unit {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  font-weight: 400;
}
.kpi-change {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: var(--font-size-xs);
  font-weight: 600;
  margin-top: var(--spacing-xs);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}
.kpi-change.up { color: var(--color-success); background: var(--color-success-dim); }
.kpi-change.down { color: var(--color-danger); background: var(--color-danger-dim); }
.kpi-change.neutral { color: var(--color-text-muted); background: var(--color-bg-tertiary); }
.kpi-sparkline {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 40px;
  opacity: 0.3;
}
.kpi-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--font-size-xs);
  margin-top: var(--spacing-sm);
}
.kpi-status .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.kpi-status .dot.green { background: var(--color-success); }
.kpi-status .dot.yellow { background: var(--color-warning); }
.kpi-status .dot.red { background: var(--color-danger); }

/* ===== CHART PANELS ===== */
.chart-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--spacing-base);
  margin-bottom: var(--spacing-xl);
}
.panel {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-lg);
  position: relative;
}
.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-md);
}
.panel-title {
  font-size: var(--font-size-md);
  font-weight: 600;
}
.panel-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
}
.panel-btn {
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
}
.panel-btn:hover { background: var(--color-bg-tertiary); color: var(--color-text-primary); }
.panel-btn.active { background: var(--color-accent-dim); color: var(--color-accent); }

/* ===== TELEMETRY CHART ===== */
.telemetry-chart {
  width: 100%;
  height: 260px;
  position: relative;
}
.telemetry-chart canvas {
  width: 100%;
  height: 100%;
}
.chart-tooltip {
  position: absolute;
  background: var(--color-bg-elevated);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--spacing-sm) var(--spacing-md);
  font-size: var(--font-size-xs);
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--transition-fast);
  box-shadow: var(--shadow-lg);
  z-index: 10;
  white-space: nowrap;
}
.chart-tooltip.visible { opacity: 1; }
.chart-tooltip .tt-label { color: var(--color-text-muted); margin-bottom: 2px; }
.chart-tooltip .tt-row { display: flex; align-items: center; gap: 6px; margin-top: 2px; }
.chart-tooltip .tt-dot { width: 8px; height: 8px; border-radius: 50%; }
.chart-legend {
  display: flex;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-sm);
}
.chart-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  cursor: pointer;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}
.chart-legend-item:hover { background: var(--color-bg-tertiary); }
.chart-legend-item.disabled { opacity: 0.3; }
.chart-legend-item .legend-dot { width: 8px; height: 8px; border-radius: 50%; }

/* ===== ORBITAL PANEL ===== */
.orbital-panel {
  display: flex;
  flex-direction: column;
}
.orbital-canvas-wrap {
  flex: 1;
  position: relative;
  min-height: 260px;
}
.orbital-canvas-wrap canvas {
  width: 100%;
  height: 100%;
}
.orbital-controls {
  display: flex;
  gap: var(--spacing-xs);
  margin-top: var(--spacing-sm);
  justify-content: center;
}
.orbital-controls button {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: var(--color-bg-tertiary);
  border: 1px solid var(--color-border);
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-md);
  transition: all var(--transition-fast);
}
.orbital-controls button:hover { background: var(--color-bg-elevated); color: var(--color-text-primary); }

/* ===== FLEET TABLE ===== */
.table-panel {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  margin-bottom: var(--spacing-xl);
  overflow: hidden;
}
.table-toolbar {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
  flex-wrap: wrap;
}
.table-search {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  background: var(--color-bg-tertiary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  min-width: 200px;
}
.table-search input {
  flex: 1;
  font-size: var(--font-size-sm);
  color: var(--color-text-primary);
}
.table-search input::placeholder { color: var(--color-text-muted); }
.table-search svg { color: var(--color-text-muted); flex-shrink: 0; }
.table-filter {
  padding: 6px 10px;
  border-radius: var(--radius-md);
  background: var(--color-bg-tertiary);
  border: 1px solid var(--color-border);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
}
.table-filter option { background: var(--color-bg-secondary); }
.table-wrap {
  overflow-x: auto;
}
.fleet-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-size-sm);
}
.fleet-table th {
  padding: 10px var(--spacing-md);
  text-align: left;
  font-weight: 600;
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--color-border);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  position: relative;
}
.fleet-table th:hover { color: var(--color-text-primary); }
.fleet-table th .sort-icon {
  display: inline-block;
  margin-left: 4px;
  opacity: 0.3;
  font-size: 10px;
}
.fleet-table th.sorted .sort-icon { opacity: 1; color: var(--color-accent); }
.fleet-table td {
  padding: 10px var(--spacing-md);
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}
.fleet-table tr {
  cursor: pointer;
  transition: background var(--transition-fast);
}
.fleet-table tbody tr:hover { background: var(--color-bg-tertiary); }
.fleet-table tbody tr:focus-visible { background: var(--color-accent-dim); }
.fleet-table .mono { font-family: var(--font-mono); font-size: var(--font-size-xs); }
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 10px;
  font-size: var(--font-size-xs);
  font-weight: 600;
}
.status-badge.nominal { background: var(--color-success-dim); color: var(--color-success); }
.status-badge.degraded { background: var(--color-warning-dim); color: var(--color-warning); }
.status-badge.critical { background: var(--color-danger-dim); color: var(--color-danger); }
.status-badge.offline { background: var(--color-bg-tertiary); color: var(--color-text-muted); }
.status-badge .status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.table-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) var(--spacing-lg);
  border-top: 1px solid var(--color-border);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}
.table-pagination {
  display: flex;
  gap: 4px;
}
.table-pagination button {
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}
.table-pagination button:hover { background: var(--color-bg-tertiary); }
.table-pagination button.active { background: var(--color-accent); color: #fff; border-color: var(--color-accent); }
.table-pagination button:disabled { opacity: 0.3; cursor: not-allowed; }

/* ===== EMPTY STATE ===== */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-3xl);
  color: var(--color-text-muted);
  text-align: center;
}
.empty-state svg { margin-bottom: var(--spacing-md); opacity: 0.4; }
.empty-state p { margin-bottom: var(--spacing-md); }
.empty-state button {
  padding: 8px 16px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  color: #fff;
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}
.empty-state button:hover { background: var(--color-accent-hover); }

/* ===== DETAIL DRAWER ===== */
.drawer-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-bg-overlay);
  z-index: 300;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}
.drawer-overlay.open { opacity: 1; visibility: visible; }
.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 420px;
  max-width: 100vw;
  background: var(--color-bg-secondary);
  border-left: 1px solid var(--color-border);
  z-index: 301;
  transform: translateX(100%);
  transition: transform var(--transition-base);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.drawer.open { transform: translateX(0); }
.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}
.drawer-title { font-size: var(--font-size-lg); font-weight: 700; }
.drawer-close {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
}
.drawer-close:hover { background: var(--color-bg-tertiary); color: var(--color-text-primary); }
.drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-lg);
}
.drawer-section {
  margin-bottom: var(--spacing-xl);
}
.drawer-section-title {
  font-size: var(--font-size-xs);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-sm);
}
.drawer-metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-sm);
}
.drawer-metric {
  background: var(--color-bg-tertiary);
  border-radius: var(--radius-md);
  padding: var(--spacing-sm) var(--spacing-md);
}
.drawer-metric-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}
.drawer-metric-value {
  font-family: var(--font-mono);
  font-size: var(--font-size-md);
  font-weight: 600;
}
.drawer-timeline {
  position: relative;
  padding-left: 20px;
}
.drawer-timeline::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--color-border);
}
.drawer-timeline-item {
  position: relative;
  padding-bottom: var(--spacing-md);
  font-size: var(--font-size-sm);
}
.drawer-timeline-item::before {
  content: '';
  position: absolute;
  left: -19px;
  top: 5px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-accent);
}
.drawer-timeline-item.warn::before { background: var(--color-warning); }
.drawer-timeline-item.error::before { background: var(--color-danger); }
.drawer-timeline-time {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}
.drawer-timeline-text { color: var(--color-text-secondary); }
.drawer-actions {
  display: flex;
  gap: var(--spacing-sm);
  padding: var(--spacing-lg);
  border-top: 1px solid var(--color-border);
}
.drawer-actions button {
  flex: 1;
  padding: 10px;
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}
.drawer-actions .btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.drawer-actions .btn-primary:hover { background: var(--color-accent-hover); }
.drawer-actions .btn-secondary {
  background: var(--color-bg-tertiary);
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border);
}
.drawer-actions .btn-secondary:hover { background: var(--color-bg-elevated); color: var(--color-text-primary); }
.drawer-actions .btn-danger {
  background: var(--color-danger-dim);
  color: var(--color-danger);
  border: 1px solid transparent;
}
.drawer-actions .btn-danger:hover { background: var(--color-danger); color: #fff; }

/* ===== EVENT STREAM ===== */
.event-stream {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  margin-bottom: var(--spacing-xl);
  overflow: hidden;
}
.event-filters {
  display: flex;
  gap: 2px;
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}
.event-filter-btn {
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
}
.event-filter-btn:hover { color: var(--color-text-primary); }
.event-filter-btn.active { background: var(--color-accent-dim); color: var(--color-accent); }
.event-list { max-height: 280px; overflow-y: auto; }
.event-item {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-md);
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.event-item:hover { background: var(--color-bg-tertiary); }
.event-item.unread { background: var(--color-accent-dim); }
.event-item.unread:hover { background: var(--color-accent-dim); }
.event-severity {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 4px;
  flex-shrink: 0;
}
.event-severity.critical { background: var(--color-danger); }
.event-severity.warning { background: var(--color-warning); }
.event-severity.info { background: var(--color-accent); }
.event-content { flex: 1; min-width: 0; }
.event-title { font-size: var(--font-size-sm); font-weight: 600; }
.event-desc { font-size: var(--font-size-xs); color: var(--color-text-muted); margin-top: 2px; }
.event-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-top: 4px;
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
}
.event-read-btn {
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
  flex-shrink: 0;
  margin-top: 2px;
}
.event-read-btn:hover { color: var(--color-accent); }

/* ===== KANBAN ===== */
.kanban-section {
  margin-bottom: var(--spacing-xl);
}
.kanban-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-base);
}
.kanban-column {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-md);
  min-height: 200px;
}
.kanban-column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-md);
  padding-bottom: var(--spacing-sm);
  border-bottom: 1px solid var(--color-border);
}
.kanban-column-title {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.kanban-column-count {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  background: var(--color-bg-tertiary);
  padding: 1px 6px;
  border-radius: 10px;
}
.kanban-card {
  background: var(--color-bg-tertiary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--spacing-sm) var(--spacing-md);
  margin-bottom: var(--spacing-sm);
  cursor: grab;
  transition: all var(--transition-fast);
  font-size: var(--font-size-sm);
}
.kanban-card:hover { border-color: var(--color-border-light); box-shadow: var(--shadow-sm); }
.kanban-card.dragging { opacity: 0.5; transform: scale(0.95); }
.kanban-card-title { font-weight: 600; margin-bottom: 2px; }
.kanban-card-desc { font-size: var(--font-size-xs); color: var(--color-text-muted); }
.kanban-card-actions {
  display: none;
  margin-top: var(--spacing-xs);
}
.kanban-card .move-menu-btn {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
}
.kanban-card .move-menu-btn:hover { background: var(--color-bg-elevated); color: var(--color-text-primary); }
.kanban-drop-zone {
  min-height: 40px;
  border: 2px dashed transparent;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}
.kanban-drop-zone.drag-over {
  border-color: var(--color-accent);
  background: var(--color-accent-dim);
}

/* ===== COMMAND PALETTE ===== */
.command-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-bg-overlay);
  z-index: 500;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 15vh;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-fast);
}
.command-overlay.open { opacity: 1; visibility: visible; }
.command-palette {
  width: 560px;
  max-width: 90vw;
  max-height: 70vh;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.command-input-wrap {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}
.command-input-wrap svg { color: var(--color-text-muted); flex-shrink: 0; }
.command-input {
  flex: 1;
  font-size: var(--font-size-md);
  color: var(--color-text-primary);
  background: none;
}
.command-input::placeholder { color: var(--color-text-muted); }
.command-results {
  overflow-y: auto;
  max-height: 50vh;
  padding: var(--spacing-xs) 0;
}
.command-group-label {
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.command-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  padding: 8px var(--spacing-lg);
  font-size: var(--font-size-sm);
  cursor: pointer;
  transition: background var(--transition-fast);
}
.command-item:hover, .command-item.selected { background: var(--color-accent-dim); color: var(--color-accent); }
.command-item svg { color: var(--color-text-muted); flex-shrink: 0; }
.command-item .cmd-label { flex: 1; }
.command-item .cmd-shortcut {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: var(--color-bg-tertiary);
}

/* ===== NOTIFICATION POPOVER ===== */
.notification-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 340px;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  z-index: 200;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-fast);
}
.notification-popover.open { opacity: 1; visibility: visible; transform: translateY(0); }
.notification-popover-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}
.notification-popover-title { font-size: var(--font-size-sm); font-weight: 700; }
.notification-popover-clear {
  font-size: var(--font-size-xs);
  color: var(--color-accent);
  cursor: pointer;
}
.notification-popover-list {
  max-height: 280px;
  overflow-y: auto;
}
.notification-item {
  display: flex;
  gap: var(--spacing-sm);
  padding: var(--spacing-md) var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
  font-size: var(--font-size-sm);
  transition: background var(--transition-fast);
}
.notification-item:hover { background: var(--color-bg-tertiary); }
.notification-item.unread { background: var(--color-accent-dim); }
.notification-item .notif-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
}
.notification-item .notif-dot.info { background: var(--color-accent); }
.notification-item .notif-dot.warn { background: var(--color-warning); }
.notification-item .notif-dot.error { background: var(--color-danger); }
.notification-item .notif-text { flex: 1; }
.notification-item .notif-time { font-size: var(--font-size-xs); color: var(--color-text-muted); font-family: var(--font-mono); }

/* ===== USER MENU ===== */
.user-menu-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 200px;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  z-index: 200;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-fast);
}
.user-menu-popover.open { opacity: 1; visibility: visible; transform: translateY(0); }
.user-menu-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: 10px var(--spacing-lg);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.user-menu-item:hover { background: var(--color-bg-tertiary); color: var(--color-text-primary); }
.user-menu-item svg { flex-shrink: 0; }
.user-menu-divider { height: 1px; background: var(--color-border); margin: 4px 0; }

/* ===== MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-bg-overlay);
  z-index: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-fast);
}
.modal-overlay.open { opacity: 1; visibility: visible; }
.modal {
  width: 400px;
  max-width: 90vw;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}
.modal-header {
  padding: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}
.modal-title { font-size: var(--font-size-lg); font-weight: 700; }
.modal-body { padding: var(--spacing-lg); }
.modal-body p { font-size: var(--font-size-sm); color: var(--color-text-secondary); line-height: 1.6; }
.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-sm);
  padding: var(--spacing-lg);
  border-top: 1px solid var(--color-border);
}
.modal-footer button {
  padding: 8px 20px;
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}
.modal-footer .btn-cancel {
  background: var(--color-bg-tertiary);
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border);
}
.modal-footer .btn-cancel:hover { background: var(--color-bg-elevated); }
.modal-footer .btn-confirm {
  background: var(--color-accent);
  color: #fff;
}
.modal-footer .btn-confirm:hover { background: var(--color-accent-hover); }
.modal-footer .btn-confirm.danger { background: var(--color-danger); }
.modal-footer .btn-confirm.danger:hover { background: #dc2626; }

/* ===== TOAST ===== */
.toast-container {
  position: fixed;
  bottom: var(--spacing-xl);
  right: var(--spacing-xl);
  z-index: 700;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-md) var(--spacing-lg);
  background: var(--color-bg-elevated);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  font-size: var(--font-size-sm);
  pointer-events: auto;
  animation: toastIn var(--transition-base) ease;
  max-width: 360px;
}
.toast.removing { animation: toastOut var(--transition-base) ease forwards; }
.toast.success { border-left: 3px solid var(--color-success); }
.toast.warning { border-left: 3px solid var(--color-warning); }
.toast.error { border-left: 3px solid var(--color-danger); }
.toast.info { border-left: 3px solid var(--color-accent); }
.toast-close {
  margin-left: auto;
  padding: 2px;
  color: var(--color-text-muted);
  cursor: pointer;
}
.toast-close:hover { color: var(--color-text-primary); }
@keyframes toastIn { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { from { opacity: 1; transform: translateX(0); } to { opacity: 0; transform: translateX(20px); } }

/* ===== SKELETON ===== */
.skeleton-overlay {
  position: fixed;
  inset: 0;
  background: var(--color-bg-primary);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  padding: var(--spacing-xl);
  transition: opacity var(--transition-slow);
}
.skeleton-overlay.hidden { opacity: 0; pointer-events: none; }
.skeleton-header {
  height: var(--header-height);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-md);
  margin-bottom: var(--spacing-lg);
}
.skeleton-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--spacing-base);
  margin-bottom: var(--spacing-lg);
}
.skeleton-card {
  height: 100px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  animation: skeletonPulse 1.5s ease-in-out infinite;
}
.skeleton-row {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--spacing-base);
  margin-bottom: var(--spacing-lg);
}
.skeleton-panel {
  height: 200px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  animation: skeletonPulse 1.5s ease-in-out infinite;
}
.skeleton-table {
  height: 300px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  animation: skeletonPulse 1.5s ease-in-out infinite;
}
@keyframes skeletonPulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.6; }
}

/* ===== FOOTER ===== */
.page-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-sm) 0;
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-top: var(--spacing-xl);
}

/* ===== SIMULATE BUTTON ===== */
.simulate-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: 6px 14px;
  border-radius: var(--radius-md);
  background: var(--color-accent-dim);
  color: var(--color-accent);
  font-size: var(--font-size-xs);
  font-weight: 600;
  border: 1px solid var(--color-accent);
  transition: all var(--transition-fast);
}
.simulate-btn:hover { background: var(--color-accent); color: #fff; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .chart-grid { grid-template-columns: 1fr; }
  .kanban-board { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .app-layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main";
  }
  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sidebar-width);
    z-index: 150;
    transform: translateX(-100%);
    transition: transform var(--transition-base);
  }
  .sidebar.mobile-open { transform: translateX(0); }
  .sidebar-toggle { display: flex; }
  .sidebar-overlay {
    position: fixed;
    inset: 0;
    background: var(--color-bg-overlay);
    z-index: 140;
    opacity: 0;
    visibility: hidden;
    transition: all var(--transition-base);
  }
  .sidebar-overlay.open { opacity: 1; visibility: visible; }
  .main-content { padding: var(--spacing-base); }
  .kpi-grid { grid-template-columns: 1fr 1fr; }
  .kanban-board { grid-template-columns: 1fr; }
  .header-search { min-width: 120px; }
  .header-search kbd { display: none; }
  .header-link-status { display: none; }
  .fleet-table { font-size: var(--font-size-xs); }
  .fleet-table th, .fleet-table td { padding: 8px var(--spacing-sm); }
  .drawer { width: 100vw; }
  .notification-popover { width: 280px; right: -40px; }
}

@media (max-width: 480px) {
  .kpi-grid { grid-template-columns: 1fr; }
  .header-mission .mission-duration { display: none; }
  .header-utc { display: none; }
  .table-toolbar { flex-direction: column; align-items: stretch; }
  .table-search { min-width: auto; }
}

/* ===== REDUCED MOTION ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .skeleton-overlay { opacity: 0; pointer-events: none; }
}

/* ===== MOBILE MOVE MENU ===== */
.move-menu {
  position: absolute;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  min-width: 140px;
  display: none;
}
.move-menu.open { display: block; }
.move-menu-item {
  padding: 8px 12px;
  font-size: var(--font-size-xs);
  cursor: pointer;
  transition: background var(--transition-fast);
}
.move-menu-item:hover { background: var(--color-bg-tertiary); }
</style>
</head>
<body>

<!-- SKELETON LOADING -->
<div class="skeleton-overlay" id="skeleton" aria-hidden="true">
  <div class="skeleton-header"></div>
  <div class="skeleton-grid">
    <div class="skeleton-card"></div>
    <div class="skeleton-card"></div>
    <div class="skeleton-card"></div>
    <div class="skeleton-card"></div>
  </div>
  <div class="skeleton-row">
    <div class="skeleton-panel"></div>
    <div class="skeleton-panel"></div>
  </div>
  <div class="skeleton-table"></div>
</div>

<!-- SIDEBAR MOBILE OVERLAY -->
<div class="sidebar-overlay" id="sidebarOverlay" aria-hidden="true"></div>

<!-- SIDEBAR TOGGLE (MOBILE) -->
<button class="sidebar-toggle" id="sidebarToggle" aria-label="Toggle navigation menu">
  <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M3 5h14M3 10h14M3 15h14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
</button>

<!-- APP LAYOUT -->
<div class="app-layout">

  <!-- HEADER -->
  <header class="header" role="banner">
    <div class="header-logo">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
        <circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="1.5"/>
        <circle cx="12" cy="12" r="3" fill="currentColor"/>
        <ellipse cx="12" cy="12" rx="10" ry="4" stroke="currentColor" stroke-width="1" opacity="0.5"/>
        <ellipse cx="12" cy="12" rx="10" ry="4" stroke="currentColor" stroke-width="1" opacity="0.5" transform="rotate(60 12 12)"/>
        <ellipse cx="12" cy="12" rx="10" ry="4" stroke="currentColor" stroke-width="1" opacity="0.5" transform="rotate(120 12 12)"/>
      </svg>
      <span>Nebula</span>
    </div>
    <div class="header-mission">
      <span class="mission-name">Asteria-7</span>
      <span class="mission-duration" id="missionDuration">T+ 000:00:00</span>
    </div>
    <div class="header-spacer"></div>
    <div class="header-link-status">
      <span class="dot" id="linkDot"></span>
      <span id="linkStatus">LINK OK</span>
    </div>
    <div class="header-utc" id="utcClock" aria-live="polite">--:--:--</div>
    <div class="header-actions">
      <button class="header-search" id="searchBtn" aria-label="Open command palette">
        <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="6" cy="6" r="4.5" stroke="currentColor" stroke-width="1.5"/><path d="M9.5 9.5L12.5 12.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <span>Search...</span>
        <kbd>⌘K</kbd>
      </button>
      <button class="header-btn" id="themeToggle" aria-label="Toggle theme">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" id="themeIcon">
          <circle cx="8" cy="8" r="3" stroke="currentColor" stroke-width="1.5"/>
          <path d="M8 1v2M8 13v2M1 8h2M13 8h2M2.93 2.93l1.41 1.41M11.66 11.66l1.41 1.41M2.93 13.07l1.41-1.41M11.66 4.34l1.41-1.41" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
        </svg>
      </button>
      <div style="position:relative">
        <button class="header-btn" id="notifBtn" aria-label="Notifications" aria-expanded="false">
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M4 6a4 4 0 018 0c0 3 2 4 2 4H2s2-1 2-4zM6 13a1 1 0 002 0" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
          <span class="badge-count" id="notifBadge" style="display:none">0</span>
        </button>
        <div class="notification-popover" id="notifPopover" role="dialog" aria-label="Notifications">
          <div class="notification-popover-header">
            <span class="notification-popover-title">Notifications</span>
            <button class="notification-popover-clear" id="notifClear">Mark all read</button>
          </div>
          <div class="notification-popover-list" id="notifList"></div>
        </div>
      </div>
      <div style="position:relative">
        <button class="header-btn" id="userBtn" aria-label="User menu" aria-expanded="false">
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><circle cx="8" cy="5" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M2 14c0-3 2.5-5 6-5s6 2 6 5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        </button>
        <div class="user-menu-popover" id="userMenu" role="menu">
          <div class="user-menu-item" role="menuitem" tabindex="0">
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="4.5" r="2.5" stroke="currentColor" stroke-width="1.2"/><path d="M1 12c0-2.5 2-4.5 6-4.5s6 2 6 4.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
            Profile
          </div>
          <div class="user-menu-item" role="menuitem" tabindex="0">
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="7" r="2.5" stroke="currentColor" stroke-width="1.2"/><path d="M7 1v2M7 11v2M1 7h2M11 7h2M2.76 2.76l1.41 1.41M9.83 9.83l1.41 1.41M2.76 11.24l1.41-1.41M9.83 4.17l1.41-1.41" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
            Preferences
          </div>
          <div class="user-menu-divider"></div>
          <div class="user-menu-item" role="menuitem" tabindex="0">
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><path d="M5 3H3a1 1 0 00-1 1v6a1 1 0 001 1h2M12 7H5M10 4l3 3-3 3" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
            Sign out
          </div>
        </div>
      </div>
    </div>
  </header>

  <!-- SIDEBAR -->
  <nav class="sidebar" id="sidebar" role="navigation" aria-label="Main navigation">
    <ul class="sidebar-nav" id="sidebarNav">
      <li class="sidebar-item active" data-page="overview" tabindex="0" role="link" aria-current="page">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><rect x="2" y="2" width="7" height="7" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="11" y="2" width="7" height="7" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="2" y="11" width="7" height="7" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="11" y="11" width="7" height="7" rx="1.5" stroke="currentColor" stroke-width="1.5"/></svg>
        <span class="item-label">Overview</span>
      </li>
      <li class="sidebar-item" data-page="fleet" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M10 3v3M10 14v3M3 10h3M14 10h3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="10" cy="3" r="1.5" fill="currentColor"/><circle cx="10" cy="17" r="1.5" fill="currentColor"/><circle cx="3" cy="10" r="1.5" fill="currentColor"/><circle cx="17" cy="10" r="1.5" fill="currentColor"/></svg>
        <span class="item-label">Fleet</span>
        <span class="item-badge" id="fleetBadge">12</span>
      </li>
      <li class="sidebar-item" data-page="telemetry" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M2 14l4-4 3 3 4-6 5 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        <span class="item-label">Telemetry</span>
      </li>
      <li class="sidebar-item" data-page="timeline" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="8" stroke="currentColor" stroke-width="1.5"/><path d="M10 5v5l3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        <span class="item-label">Mission Timeline</span>
      </li>
      <li class="sidebar-item" data-page="incidents" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M10 2L2 18h16L10 2z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><path d="M10 8v4M10 14v.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <span class="item-label">Incidents</span>
        <span class="item-badge danger" id="incidentBadge">3</span>
      </li>
      <li class="sidebar-item" data-page="payloads" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><rect x="3" y="6" width="14" height="10" rx="2" stroke="currentColor" stroke-width="1.5"/><path d="M7 6V4a3 3 0 016 0v2" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <span class="item-label">Payloads</span>
      </li>
      <li class="sidebar-item" data-page="settings" tabindex="0" role="link">
        <svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M10 2v2M10 16v2M2 10h2M16 10h2M4.22 4.22l1.41 1.41M14.36 14.36l1.41 1.41M4.22 15.78l1.41-1.41M14.36 5.64l1.41-1.41" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <span class="item-label">Settings</span>
      </li>
    </ul>
    <div class="sidebar-footer">
      <span>v2.6.1</span>
    </div>
  </nav>

  <!-- MAIN CONTENT -->
  <main class="main-content" id="mainContent" role="main">

    <!-- SECTION HEADER -->
    <div class="section-header">
      <div>
        <h1 class="section-title">Mission Overview</h1>
        <p class="section-subtitle">Last sync: <span id="lastSync">--</span> · <button class="simulate-btn" id="simulateBtn">
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M2 6h8M6 2v8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
          Simulate Telemetry Update
        </button></p>
      </div>
      <div class="time-range-group" role="tablist" aria-label="Time range">
        <button class="time-range-btn" data-range="1h" role="tab">1H</button>
        <button class="time-range-btn" data-range="6h" role="tab">6H</button>
        <button class="time-range-btn active" data-range="24h" role="tab" aria-selected="true">24H</button>
        <button class="time-range-btn" data-range="7d" role="tab">7D</button>
      </div>
    </div>

    <!-- KPI CARDS -->
    <div class="kpi-grid" id="kpiGrid">
      <div class="kpi-card nominal">
        <div class="kpi-label">Online Probes</div>
        <div class="kpi-value" id="kpiOnline">9<span class="kpi-unit"> / 12</span></div>
        <div class="kpi-change up" id="kpiOnlineChange">▲ +1 from last hour</div>
        <div class="kpi-status"><span class="dot green"></span> Nominal</div>
        <canvas class="kpi-sparkline" id="sparkOnline" height="40"></canvas>
      </div>
      <div class="kpi-card info">
        <div class="kpi-label">Avg Signal Delay</div>
        <div class="kpi-value" id="kpiDelay">142<span class="kpi-unit"> ms</span></div>
        <div class="kpi-change down" id="kpiDelayChange">▼ -8ms from last hour</div>
        <div class="kpi-status"><span class="dot green"></span> Within tolerance</div>
        <canvas class="kpi-sparkline" id="sparkDelay" height="40"></canvas>
      </div>
      <div class="kpi-card nominal">
        <div class="kpi-label">Downlink Today</div>
        <div class="kpi-value" id="kpiDownlink">4.7<span class="kpi-unit"> TB</span></div>
        <div class="kpi-change up" id="kpiDownlinkChange">▲ +12% from yesterday</div>
        <div class="kpi-status"><span class="dot green"></span> On target</div>
        <canvas class="kpi-sparkline" id="sparkDownlink" height="40"></canvas>
      </div>
      <div class="kpi-card danger">
        <div class="kpi-label">Critical Events</div>
        <div class="kpi-value" id="kpiCritical">3</div>
        <div class="kpi-change neutral" id="kpiCriticalChange">— unchanged</div>
        <div class="kpi-status"><span class="dot red"></span> Requires attention</div>
        <canvas class="kpi-sparkline" id="sparkCritical" height="40"></canvas>
      </div>
    </div>

    <!-- CHART GRID -->
    <div class="chart-grid">
      <!-- TELEMETRY CHART -->
      <div class="panel">
        <div class="panel-header">
          <span class="panel-title">Telemetry Trends</span>
          <div class="panel-actions">
            <button class="panel-btn active" data-series="signal" aria-label="Toggle signal strength">Signal</button>
            <button class="panel-btn active" data-series="thermal" aria-label="Toggle thermal load">Thermal</button>
            <button class="panel-btn active" data-series="power" aria-label="Toggle power reserve">Power</button>
          </div>
        </div>
        <div class="telemetry-chart" id="telemetryChart">
          <canvas id="telemetryCanvas"></canvas>
          <div class="chart-tooltip" id="chartTooltip"></div>
        </div>
        <div class="chart-legend" id="chartLegend">
          <div class="chart-legend-item" data-series="signal"><span class="legend-dot" style="background:#06b6d4"></span> Signal Strength (dBm)</div>
          <div class="chart-legend-item" data-series="thermal"><span class="legend-dot" style="background:#f59e0b"></span> Thermal Load (°C)</div>
          <div class="chart-legend-item" data-series="power"><span class="legend-dot" style="background:#10b981"></span> Power Reserve (%)</div>
        </div>
      </div>

      <!-- ORBITAL PANEL -->
      <div class="panel orbital-panel">
        <div class="panel-header">
          <span class="panel-title">Orbital Map</span>
        </div>
        <div class="orbital-canvas-wrap">
          <canvas id="orbitalCanvas"></canvas>
        </div>
        <div class="orbital-controls">
          <button id="orbitZoomIn" aria-label="Zoom in">+</button>
          <button id="orbitZoomOut" aria-label="Zoom out">−</button>
          <button id="orbitReset" aria-label="Reset zoom">⟲</button>
        </div>
      </div>
    </div>

    <!-- FLEET TABLE -->
    <div class="table-panel">
      <div class="panel-header" style="padding: var(--spacing-md) var(--spacing-lg); border-bottom: 1px solid var(--color-border);">
        <span class="panel-title">Fleet Status</span>
      </div>
      <div class="table-toolbar">
        <div class="table-search">
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="6" cy="6" r="4.5" stroke="currentColor" stroke-width="1.5"/><path d="M9.5 9.5L12.5 12.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
          <input type="text" id="tableSearch" placeholder="Search probes..." aria-label="Search probes">
        </div>
        <select class="table-filter" id="tableFilter" aria-label="Filter by status">
          <option value="all">All Status</option>
          <option value="nominal">Nominal</option>
          <option value="degraded">Degraded</option>
          <option value="critical">Critical</option>
          <option value="offline">Offline</option>
        </select>
      </div>
      <div class="table-wrap">
        <table class="fleet-table" id="fleetTable" aria-label="Fleet status table">
          <thead>
            <tr>
              <th data-sort="name" tabindex="0">Name <span class="sort-icon">↕</span></th>
              <th data-sort="model" tabindex="0">Model <span class="sort-icon">↕</span></th>
              <th data-sort="status" tabindex="0">Status <span class="sort-icon">↕</span></th>
              <th data-sort="distance" tabindex="0">Distance <span class="sort-icon">↕</span></th>
              <th data-sort="signal" tabindex="0">Signal <span class="sort-icon">↕</span></th>
              <th data-sort="temp" tabindex="0">Temp <span class="sort-icon">↕</span></th>
              <th data-sort="power" tabindex="0">Power <span class="sort-icon">↕</span></th>
              <th data-sort="lastContact" tabindex="0">Last Contact <span class="sort-icon">↕</span></th>
              <th data-sort="operator" tabindex="0">Operator <span class="sort-icon">↕</span></th>
            </tr>
          </thead>
          <tbody id="fleetTableBody"></tbody>
        </table>
        <div class="empty-state" id="emptyState" style="display:none">
          <svg width="48" height="48" viewBox="0 0 48 48" fill="none"><circle cx="24" cy="24" r="20" stroke="currentColor" stroke-width="1.5"/><path d="M16 24h16M24 16v16" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
          <p>No probes match your filters.</p>
          <button id="clearFilters">Clear Filters</button>
        </div>
      </div>
      <div class="table-footer">
        <span id="tableInfo">Showing 1-8 of 12 probes</span>
        <div class="table-pagination" id="tablePagination"></div>
      </div>
    </div>

    <!-- EVENT STREAM -->
    <div class="event-stream">
      <div class="panel-header" style="padding: var(--spacing-md) var(--spacing-lg); border-bottom: 1px solid var(--color-border);">
        <span class="panel-title">Recent Events</span>
      </div>
      <div class="event-filters" role="tablist" aria-label="Event filters">
        <button class="event-filter-btn active" data-filter="all" role="tab" aria-selected="true">All</button>
        <button class="event-filter-btn" data-filter="critical" role="tab">Critical</button>
        <button class="event-filter-btn" data-filter="warning" role="tab">Warning</button>
        <button class="event-filter-btn" data-filter="info" role="tab">Info</button>
      </div>
      <div class="event-list" id="eventList" role="list"></div>
    </div>

    <!-- KANBAN -->
    <div class="kanban-section">
      <div class="section-header">
        <h2 class="section-title" style="font-size:var(--font-size-lg)">Mission Phases</h2>
      </div>
      <div class="kanban-board" id="kanbanBoard">
        <div class="kanban-column" data-column="planning">
          <div class="kanban-column-header">
            <span class="kanban-column-title">Planning</span>
            <span class="kanban-column-count" id="countPlanning">0</span>
          </div>
          <div class="kanban-drop-zone" id="zonePlanning"></div>
        </div>
        <div class="kanban-column" data-column="in-transit">
          <div class="kanban-column-header">
            <span class="kanban-column-title">In Transit</span>
            <span class="kanban-column-count" id="countTransit">0</span>
          </div>
          <div class="kanban-drop-zone" id="zoneTransit"></div>
        </div>
        <div class="kanban-column" data-column="orbit">
          <div class="kanban-column-header">
            <span class="kanban-column-title">Orbit</span>
            <span class="kanban-column-count" id="countOrbit">0</span>
          </div>
          <div class="kanban-drop-zone" id="zoneOrbit"></div>
        </div>
        <div class="kanban-column" data-column="complete">
          <div class="kanban-column-header">
            <span class="kanban-column-title">Complete</span>
            <span class="kanban-column-count" id="countComplete">0</span>
          </div>
          <div class="kanban-drop-zone" id="zoneComplete"></div>
        </div>
      </div>
    </div>

    <!-- FOOTER -->
    <div class="page-footer">
      <span>Data updated: <span id="footerUpdate">--</span></span>
      <span>Nebula Mission Control v2.6.1</span>
    </div>
  </main>
</div>

<!-- DETAIL DRAWER -->
<div class="drawer-overlay" id="drawerOverlay" aria-hidden="true"></div>
<div class="drawer" id="drawer" role="dialog" aria-label="Probe details" aria-hidden="true">
  <div class="drawer-header">
    <span class="drawer-title" id="drawerTitle">Probe Details</span>
    <button class="drawer-close" id="drawerClose" aria-label="Close drawer">
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none"><path d="M4 4l10 10M14 4L4 14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
    </button>
  </div>
  <div class="drawer-body" id="drawerBody"></div>
  <div class="drawer-actions">
    <button class="btn-secondary" id="drawerPing">Ping Probe</button>
    <button class="btn-primary" id="drawerReboot">Reboot Systems</button>
    <button class="btn-danger" id="drawerAbort">Abort Mission</button>
  </div>
</div>

<!-- COMMAND PALETTE -->
