<script>
(function() {
  'use strict';

  // ===== DETERMINISTIC DATA =====
  const PROBE_NAMES = [
    'Hermes-1', 'Hermes-2', 'Hermes-3', 'Athena-1', 'Athena-2',
    'Apollo-1', 'Apollo-2', 'Apollo-3', 'Artemis-1', 'Artemis-2',
    'Perseus-1', 'Perseus-2'
  ];
  const MODELS = ['NX-4000', 'NX-4000', 'NX-4000', 'NX-5000', 'NX-5000', 'NX-3000', 'NX-3000', 'NX-3000', 'NX-5000', 'NX-5000', 'NX-4000', 'NX-4000'];
  const OPERATORS = ['Dr. Chen', 'Cmdr. Vasquez', 'Dr. Okonkwo', 'Lt. Petrov', 'Dr. Tanaka', 'Cmdr. Vasquez', 'Dr. Chen', 'Lt. Petrov', 'Dr. Okonkwo', 'Dr. Tanaka', 'Cmdr. Vasquez', 'Dr. Chen'];
  const STATUSES = ['nominal', 'nominal', 'nominal', 'degraded', 'nominal', 'nominal', 'critical', 'nominal', 'nominal', 'offline', 'nominal', 'degraded'];

  // Deterministic fleet data
  const fleetData = PROBE_NAMES.map((name, i) => ({
    id: i,
    name,
    model: MODELS[i],
    status: STATUSES[i],
    distance: (1.2 + i * 0.3).toFixed(1) + ' AU',
    distanceNum: 1.2 + i * 0.3,
    signal: Math.round(72 - i * 3 + (i % 3) * 2),
    temp: Math.round(22 + i * 2 - (i % 4) * 1.5),
    power: Math.round(85 - i * 3 + (i % 5) * 2),
    lastContact: `2025-01-15T${String(10 + i).padStart(2,'0')}:${String((i*7)%60).padStart(2,'0')}:00Z`,
    operator: OPERATORS[i]
  }));

  // Events data
  const eventsData = [
    { id: 1, severity: 'critical', title: 'Apollo-3 thermal runaway detected', desc: 'Core temperature exceeded 85°C threshold. Auto-cooling engaged.', time: '2025-01-15T14:32:00Z', unread: true },
    { id: 2, severity: 'warning', title: 'Perseus-2 signal degradation', desc: 'Signal strength dropped below -80 dBm. Antenna realignment scheduled.', time: '2025-01-15T13:15:00Z', unread: true },
    { id: 3, severity: 'info', title: 'Hermes-1 orbit insertion confirmed', desc: 'Probe successfully entered Asteria-7 polar orbit at 400km altitude.', time: '2025-01-15T12:00:00Z', unread: false },
    { id: 4, severity: 'critical', title: 'Artemis-2 power cell failure', desc: 'Secondary power cell offline. Switching to backup reserves.', time: '2025-01-15T11:45:00Z', unread: true },
    { id: 5, severity: 'warning', title: 'Athena-1 navigation drift', desc: 'Positional accuracy degraded by 0.3%. Recalibration in progress.', time: '2025-01-15T10:20:00Z', unread: false },
    { id: 6, severity: 'info', title: 'Fleet-wide telemetry sync complete', desc: 'All 12 probes synchronized. Data integrity verified at 99.7%.', time: '2025-01-15T09:00:00Z', unread: false },
    { id: 7, severity: 'info', title: 'Hermes-2 payload deployment successful', desc: 'Spectrometer array deployed and calibrated.', time: '2025-01-15T08:30:00Z', unread: false },
    { id: 8, severity: 'warning', title: 'Apollo-1 communication latency spike', desc: 'Latency increased to 210ms during solar conjunction window.', time: '2025-01-15T07:15:00Z', unread: false }
  ];

  // Kanban data
  const kanbanData = {
    planning: [
      { id: 'k1', title: 'Surface Sample Collection', desc: 'Phase 3B — Artemis probes' },
      { id: 'k2', title: 'Spectrometer Calibration', desc: 'Phase 4A — Athena probes' }
    ],
    'in-transit': [
      { id: 'k3', title: 'Orbital Insertion Burn', desc: 'Phase 2C — Hermes fleet' },
      { id: 'k4', title: 'Trajectory Correction', desc: 'Phase 2D — Apollo fleet' }
    ],
    orbit: [
      { id: 'k5', title: 'Polar Mapping Survey', desc: 'Phase 1A — Perseus probes' },
      { id: 'k6', title: 'Atmospheric Analysis', desc: 'Phase 1B — Athena-1' }
    ],
    complete: [
      { id: 'k7', title: 'Launch Sequence', desc: 'Phase 0 — All probes' },
      { id: 'k8', title: 'Deep Space Transit', desc: 'Phase 1 — All probes' }
    ]
  };

  // Telemetry data (deterministic)
  const telemetryPoints = 48;
  const telemetryData = {
    signal: [],
    thermal: [],
    power: []
  };
  for (let i = 0; i < telemetryPoints; i++) {
    telemetryData.signal.push(-45 + Math.sin(i * 0.3) * 15 + Math.cos(i * 0.7) * 8);
    telemetryData.thermal.push(28 + Math.sin(i * 0.2) * 12 + Math.cos(i * 0.5) * 5);
    telemetryData.power.push(78 + Math.sin(i * 0.15) * 10 - i * 0.15);
  }

  // Sparkline data
  const sparkData = {
    online: [8, 8, 9, 9, 8, 9, 9, 10, 9, 9, 9, 9],
    delay: [150, 148, 145, 143, 146, 142, 144, 141, 143, 142, 140, 142],
    downlink: [3.2, 3.5, 3.8, 4.0, 4.1, 4.3, 4.4, 4.5, 4.6, 4.6, 4.7, 4.7],
    critical: [2, 2, 2, 3, 3, 3, 3, 3, 3, 3, 3, 3]
  };

  // Notifications
  const notifications = [
    { id: 1, type: 'error', text: 'Apollo-3 thermal alert requires review', time: '14:32 UTC', unread: true },
    { id: 2, type: 'warn', text: 'Perseus-2 signal below threshold', time: '13:15 UTC', unread: true },
    { id: 3, type: 'info', text: 'Hermes-1 orbit insertion confirmed', time: '12:00 UTC', unread: false },
    { id: 4, type: 'error', text: 'Artemis-2 power cell failure', time: '11:45 UTC', unread: true },
    { id: 5, type: 'info', text: 'Fleet telemetry sync complete', time: '09:00 UTC', unread: false }
  ];

  // ===== STATE =====
  let state = {
    theme: localStorage.getItem('nebula-theme') || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark'),
    sidebarCollapsed: localStorage.getItem('nebula-sidebar') === 'collapsed',
    sidebarMobileOpen: false,
    tableSort: { key: 'name', dir: 'asc' },
    tableFilter: 'all',
    tableSearch: '',
    tablePage: 1,
    tablePageSize: 8,
    eventFilter: 'all',
    timeRange: '24h',
    telemetryVisible: { signal: true, thermal: true, power: true },
    orbitZoom: 1,
    kanban: JSON.parse(localStorage.getItem('nebula-kanban')) || JSON.parse(JSON.stringify(kanbanData)),
    notifications: JSON.parse(localStorage.getItem('nebula-notifications')) || JSON.parse(JSON.stringify(notifications)),
    events: JSON.parse(localStorage.getItem('nebula-events')) || JSON.parse(JSON.stringify(eventsData)),
    simStep: parseInt(localStorage.getItem('nebula-simstep') || '0'),
    selectedProbe: null,
    commandOpen: false,
    notifOpen: false,
    userMenuOpen: false,
    drawerOpen: false,
    modalOpen: false,
    missionStart: new Date('2024-06-15T00:00:00Z').getTime()
  };

  // ===== DOM REFS =====
  const $ = id => document.getElementById(id);
  const $$ = sel => document.querySelectorAll(sel);

  // ===== INIT =====
  function init() {
    applyTheme();
    applySidebarState();
    renderFleetTable();
    renderEvents();
    renderKanban();
    renderNotifications();
    renderSparklines();
    renderTelemetryChart();
    renderOrbitalMap();
    updateClock();
    updateMissionDuration();
    updateFooterTime();
    setupEventListeners();
    setupKeyboardShortcuts();

    // Remove skeleton
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    setTimeout(() => {
      $('skeleton').classList.add('hidden');
      if (reducedMotion) {
        setTimeout(() => $('skeleton').remove(), 50);
      }
    }, reducedMotion ? 10 : 500);
  }

  // ===== THEME =====
  function applyTheme() {
    document.documentElement.setAttribute('data-theme', state.theme);
    localStorage.setItem('nebula-theme', state.theme);
    updateThemeIcon();
  }
  function toggleTheme() {
    state.theme = state.theme === 'dark' ? 'light' : 'dark';
    applyTheme();
  }
  function updateThemeIcon() {
    const icon = $('themeIcon');
    if (state.theme === 'dark') {
      icon.innerHTML = '<circle cx="8" cy="8" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M8 1v2M8 13v2M1 8h2M13 8h2M2.93 2.93l1.41 1.41M11.66 11.66l1.41 1.41M2.93 13.07l1.41-1.41M11.66 4.34l1.41-1.41" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>';
    } else {
      icon.innerHTML = '<path d="M12 7a5 5 0 01-5 5 5 5 0 01-5-5 5 5 0 015-5c.8 0 1.5.2 2.2.5C8.5 3.5 7 5.5 7 8c0 2.5 1.5 4.5 3.5 5.5A5 5 0 0012 7z" stroke="currentColor" stroke-width="1.5" fill="none"/>';
    }
  }

  // ===== SIDEBAR =====
  function applySidebarState() {
    const sb = $('sidebar');
    if (state.sidebarCollapsed && window.innerWidth > 768) {
      sb.classList.add('collapsed');
    }
  }
  function toggleSidebar() {
    if (window.innerWidth <= 768) {
      state.sidebarMobileOpen = !state.sidebarMobileOpen;
      $('sidebar').classList.toggle('mobile-open', state.sidebarMobileOpen);
      $('sidebarOverlay').classList.toggle('open', state.sidebarMobileOpen);
      $('sidebarOverlay').setAttribute('aria-hidden', !state.sidebarMobileOpen);
    } else {
      state.sidebarCollapsed = !state.sidebarCollapsed;
      $('sidebar').classList.toggle('collapsed', state.sidebarCollapsed);
      localStorage.setItem('nebula-sidebar', state.sidebarCollapsed ? 'collapsed' : 'expanded');
    }
  }
  function closeSidebarMobile() {
    state.sidebarMobileOpen = false;
    $('sidebar').classList.remove('mobile-open');
    $('sidebarOverlay').classList.remove('open');
    $('sidebarOverlay').setAttribute('aria-hidden', 'true');
  }

  // ===== CLOCK =====
  function updateClock() {
    const now = new Date();
    const h = String(now.getUTCHours()).padStart(2, '0');
    const m = String(now.getUTCMinutes()).padStart(2, '0');
    const s = String(now.getUTCSeconds()).padStart(2, '0');
    $('utcClock').textContent = `${h}:${m}:${s} UTC`;
  }
  function updateMissionDuration() {
    const elapsed = Date.now() - state.missionStart;
    const days = Math.floor(elapsed / 86400000);
    const hours = Math.floor((elapsed % 86400000) / 3600000);
    const mins = Math.floor((elapsed % 3600000) / 60000);
    const secs = Math.floor((elapsed % 60000) / 1000);
    $('missionDuration').textContent = `T+ ${String(days).padStart(3,'0')}:${String(hours).padStart(2,'0')}:${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;
  }
  function updateFooterTime() {
    const now = new Date();
    $('footerUpdate').textContent = now.toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
  }

  // ===== SPARKLINES =====
  function renderSparklines() {
    drawSparkline('sparkOnline', sparkData.online, '#10b981');
    drawSparkline('sparkDelay', sparkData.delay, '#06b6d4');
    drawSparkline('sparkDownlink', sparkData.downlink, '#10b981');
    drawSparkline('sparkCritical', sparkData.critical, '#ef4444');
  }
  function drawSparkline(canvasId, data, color) {
    const canvas = $(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    const w = rect.width;
    const h = rect.height;
    const min = Math.min(...data);
    const max = Math.max(...data);
    const range = max - min || 1;
    const step = w / (data.length - 1);

    ctx.clearRect(0, 0, w, h);
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.lineJoin = 'round';
    data.forEach((v, i) => {
      const x = i * step;
      const y = h - ((v - min) / range) * (h - 4) - 2;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Fill
    ctx.lineTo(w, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fillStyle = color.replace(')', ',0.1)').replace('rgb', 'rgba');
    ctx.fill();
  }

  // ===== TELEMETRY CHART =====
  function renderTelemetryChart() {
    const canvas = $('telemetryCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const pad = { top: 20, right: 20, bottom: 35, left: 50 };
    const cw = w - pad.left - pad.right;
    const ch = h - pad.top - pad.bottom;

    ctx.clearRect(0, 0, w, h);

    // Grid
    ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--color-border').trim();
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= 5; i++) {
      const y = pad.top + (ch / 5) * i;
      ctx.beginPath();
      ctx.moveTo(pad.left, y);
      ctx.lineTo(w - pad.right, y);
      ctx.stroke();
    }

    // Y-axis labels
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--color-text-muted').trim();
    ctx.font = '10px ' + getComputedStyle(document.documentElement).getPropertyValue('--font-mono').trim();
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = pad.top + (ch / 5) * i;
      const val = 100 - i * 20;
      ctx.fillText(val, pad.left - 8, y + 4);
    }

    // X-axis labels
    ctx.textAlign = 'center';
    const timeLabels = ['00:00', '04:00', '08:00', '12:00', '16:00', '20:00', '24:00'];
    timeLabels.forEach((label, i) => {
      const x = pad.left + (cw / (timeLabels.length - 1)) * i;
      ctx.fillText(label, x, h - pad.bottom + 18);
    });

    // Draw series
    const seriesColors = { signal: '#06b6d4', thermal: '#f59e0b', power: '#10b981' };
    const seriesKeys = Object.keys(state.telemetryVisible).filter(k => state.telemetryVisible[k]);

    seriesKeys.forEach(key => {
      const data = telemetryData[key];
      const color = seriesColors[key];
      const min = Math.min(...data);
      const max = Math.max(...data);
      const range = max - min || 1;
      const step = cw / (data.length - 1);

      ctx.beginPath();
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      ctx.lineJoin = 'round';
      data.forEach((v, i) => {
        const x = pad.left + i * step;
        const y = pad.top + ch - ((v - min) / range) * ch;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // Current point highlight
      const lastX = pad.left + (data.length - 1) * step;
      const lastY = pad.top + ch - ((data[data.length - 1] - min) / range) * ch;
      ctx.beginPath();
      ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(lastX, lastY, 7, 0, Math.PI * 2);
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.3;
      ctx.stroke();
      ctx.globalAlpha = 1;
    });

    // Store chart info for tooltip
    canvas._chartInfo = { pad, cw, ch, w, h };
  }

  // ===== ORBITAL MAP =====
  function renderOrbitalMap() {
    const canvas = $('orbitalCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const cx = w / 2;
    const cy = h / 2;
    const zoom = state.orbitZoom;

    ctx.clearRect(0, 0, w, h);

    const bg = getComputedStyle(document.documentElement).getPropertyValue('--color-bg-secondary').trim();
    const border = getComputedStyle(document.documentElement).getPropertyValue('--color-border').trim();
    const muted = getComputedStyle(document.documentElement).getPropertyValue('--color-text-muted').trim();
    const accent = getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim();

    // Background
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    // Grid circles
    ctx.strokeStyle = border;
    ctx.lineWidth = 0.5;
    for (let r = 30; r <= 120; r += 30) {
      ctx.beginPath();
      ctx.arc(cx, cy, r * zoom, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Earth
    ctx.beginPath();
    ctx.arc(cx, cy, 12 * zoom, 0, Math.PI * 2);
    ctx.fillStyle = '#3b82f6';
    ctx.fill();
    ctx.fillStyle = muted;
    ctx.font = '10px ' + getComputedStyle(document.documentElement).getPropertyValue('--font-sans').trim();
    ctx.textAlign = 'center';
    ctx.fillText('Earth', cx, cy + 24 * zoom);

    // Moon
    const moonAngle = Date.now() * 0.0001;
    const moonR = 40 * zoom;
    const moonX = cx + Math.cos(moonAngle) * moonR;
    const moonY = cy + Math.sin(moonAngle) * moonR;
    ctx.beginPath();
    ctx.arc(moonX, moonY, 4 * zoom, 0, Math.PI * 2);
    ctx.fillStyle = '#94a3b8';
    ctx.fill();
    ctx.fillText('Moon', moonX, moonY + 12 * zoom);

    // Asteria-7
    const astR = 100 * zoom;
    const astX = cx + Math.cos(1.2) * astR;
    const astY = cy + Math.sin(1.2) * astR;
    ctx.beginPath();
    ctx.arc(astX, astY, 8 * zoom, 0, Math.PI * 2);
    ctx.fillStyle = '#f59e0b';
    ctx.fill();
    ctx.fillText('Asteria-7', astX, astY + 18 * zoom);

    // Orbits
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.4;
    // Orbit 1
    ctx.beginPath();
    ctx.ellipse(cx, cy, 60 * zoom, 45 * zoom, 0.3, 0, Math.PI * 2);
    ctx.stroke();
    // Orbit 2
    ctx.beginPath();
    ctx.ellipse(cx, cy, 80 * zoom, 55 * zoom, -0.2, 0, Math.PI * 2);
    ctx.stroke();
    // Orbit 3
    ctx.beginPath();
    ctx.ellipse(cx, cy, 95 * zoom, 70 * zoom, 0.5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // Probe dots on orbits
    const probeAngles = [0.5, 1.8, 3.2, 4.5, 5.8];
    probeAngles.forEach((angle, i) => {
      const orbitIdx = i % 3;
      const radii = [[60, 45], [80, 55], [95, 70]];
      const tilts = [0.3, -0.2, 0.5];
      const rx = radii[orbitIdx][0] * zoom;
      const ry = radii[orbitIdx][1] * zoom;
      const tilt = tilts[orbitIdx];
      const px = cx + Math.cos(angle) * rx * Math.cos(tilt) - Math.sin(angle) * ry * Math.sin(tilt);
      const py = cy + Math.cos(angle) * rx * Math.sin(tilt) + Math.sin(angle) * ry * Math.cos(tilt);
      ctx.beginPath();
      ctx.arc(px, py, 3 * zoom, 0, Math.PI * 2);
      ctx.fillStyle = accent;
      ctx.fill();
    });
  }

  // ===== FLEET TABLE =====
  function getFilteredFleet() {
    let data = [...fleetData];
    if (state.tableFilter !== 'all') {
      data = data.filter(p => p.status === state.tableFilter);
    }
    if (state.tableSearch) {
      const q = state.tableSearch.toLowerCase();
      data = data.filter(p => p.name.toLowerCase().includes(q) || p.model.toLowerCase().includes(q) || p.operator.toLowerCase().includes(q));
    }
    // Sort
    const key = state.tableSort.key;
    const dir = state.tableSort.dir === 'asc' ? 1 : -1;
    data.sort((a, b) => {
      let va = a[key], vb = b[key];
      if (key === 'distance' || key === 'signal' || key === 'temp' || key === 'power') {
        va = parseFloat(va);
        vb = parseFloat(vb);
      }
      if (typeof va === 'string') {
        return va.localeCompare(vb) * dir;
      }
      return (va - vb) * dir;
    });
    return data;
  }

  function renderFleetTable() {
    const filtered = getFilteredFleet();
    const tbody = $('fleetTableBody');
    const emptyState = $('emptyState');
    const totalPages = Math.ceil(filtered.length / state.tablePageSize);
    const start = (state.tablePage - 1) * state.tablePageSize;
    const pageData = filtered.slice(start, start + state.tablePageSize);

    // Update sort indicators
    $$('.fleet-table th').forEach(th => {
      th.classList.toggle('sorted', th.dataset.sort === state.tableSort.key);
      const icon = th.querySelector('.sort-icon');
      if (icon) {
        icon.textContent = th.dataset.sort === state.tableSort.key ? (state.tableSort.dir === 'asc' ? '↑' : '↓') : '↕';
      }
    });

    if (filtered.length === 0) {
      tbody.innerHTML = '';
      emptyState.style.display = 'flex';
      $('tableInfo').textContent = 'No matching probes';
      $('tablePagination').innerHTML = '';
      return;
    }

    emptyState.style.display = 'none';
    tbody.innerHTML = pageData.map(p => `
      <tr tabindex="0" data-id="${p.id}" role="row" aria-label="${p.name}">
        <td><strong>${p.name}</strong></td>
        <td class="mono">${p.model}</td>
        <td><span class="status-badge ${p.status}"><span class="status-dot"></span>${capitalize(p.status)}</span></td>
        <td class="mono">${p.distance}</td>
        <td class="mono">${p.signal} dBm</td>
        <td class="mono">${p.temp}°C</td>
        <td class="mono">${p.power}%</td>
        <td class="mono">${p.lastContact.slice(11,16)} UTC</td>
        <td>${p.operator}</td>
      </tr>
    `).join('');

    $('tableInfo').textContent = `Showing ${start + 1}-${Math.min(start + state.tablePageSize, filtered.length)} of ${filtered.length} probes`;

    // Pagination
    let pagHtml = '';
    if (totalPages > 1) {
      pagHtml += `<button ${state.tablePage === 1 ? 'disabled' : ''} data-page="${state.tablePage - 1}">‹</button>`;
      for (let i = 1; i <= totalPages; i++) {
        pagHtml += `<button class="${i === state.tablePage ? 'active' : ''}" data-page="${i}">${i}</button>`;
      }
      pagHtml += `<button ${state.tablePage === totalPages ? 'disabled' : ''} data-page="${state.tablePage + 1}">›</button>`;
    }
    $('tablePagination').innerHTML = pagHtml;
  }

  function capitalize(s) { return s.charAt(0).toUpperCase() + s.slice(1); }

  // ===== EVENTS =====
  function renderEvents() {
    const list = $('eventList');
